WITH base AS (SELECT id, account_type, balance, opened_date, status, LENGTH(account_type) AS account_type_length FROM accounts WHERE status IS NOT NULL), kept AS (SELECT s.* FROM base s WHERE EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.account_id = 23)), not_flagged AS (SELECT s.* FROM kept s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time < s.opened_date)), enriched AS (SELECT *, MIN(balance) OVER (PARTITION BY status) AS status_min_balance, SUM(balance) OVER (PARTITION BY status ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance, DENSE_RANK() OVER w_ordered AS account_type_length_dense_rank FROM not_flagged WINDOW w_ordered AS (PARTITION BY status, account_type ORDER BY account_type_length DESC NULLS LAST)), base_accounts AS (SELECT *, LEAST(account_type_length_dense_rank, cumulative_balance) AS least_account_type_length_dense_rank_cumulative_balance, COALESCE(status, 'DIRECT') AS status_filled FROM enriched WHERE status IS NOT DISTINCT FROM 'OPEN'), with_latest AS (SELECT s.id, s.account_type, s.opened_date, s.status_min_balance, s.status_filled, latest.transaction_txn_type FROM base_accounts s LEFT JOIN LATERAL (SELECT c.txn_type AS transaction_txn_type FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE), not_flagged_accounts AS (SELECT s.* FROM with_latest s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time >= s.opened_date)) SELECT id, account_type, opened_date, status_min_balance, status_filled FROM not_flagged_accounts
